use core::marker::PhantomData;
use frame_support::{
    traits::Get,
    weights::{constants::RocksDbWeight, Weight},
};

/// Weight functions required by prediction-control governance calls.
/// Prediction-control 治理调用所需的权重函数。
pub trait WeightInfo {
    fn set_prediction_mode() -> Weight;
    fn set_module_enabled() -> Weight;
}

/// Nexus benchmark-generated database-weight adapter.
/// Nexus benchmark 生成的数据库权重适配器。
pub struct SubstrateWeight<T>(PhantomData<T>);

impl<T: frame_system::Config> WeightInfo for SubstrateWeight<T> {
    fn set_prediction_mode() -> Weight {
        Weight::from_parts(26_205_000, 1_632).saturating_add(T::DbWeight::get().reads_writes(1, 1))
    }

    fn set_module_enabled() -> Weight {
        Weight::from_parts(22_614_000, 0).saturating_add(T::DbWeight::get().writes(1))
    }
}

impl WeightInfo for () {
    fn set_prediction_mode() -> Weight {
        Weight::from_parts(26_205_000, 1_632)
            .saturating_add(RocksDbWeight::get().reads_writes(1, 1))
    }

    fn set_module_enabled() -> Weight {
        Weight::from_parts(22_614_000, 0).saturating_add(RocksDbWeight::get().writes(1))
    }
}
